$steps = [];
$ok = true;

// 1. Connect
try {
    $pdo = new PDO("mysql:host=".DB_HOST.";dbname=".DB_NAME.";charset=utf8mb4", DB_USER, DB_PASS,
        [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 10]);
    $steps[] = ['ok','✅','تم الاتصال بـ MySQL بنجاح'];
} catch (Exception $e) {
    $steps[] = ['err','❌','فشل الاتصال: '.$e->getMessage()]; $ok=false;
}

// 2. Create DB (Skipped for InfinityFree)
// InfinityFree does not allow CREATE DATABASE, it's already created.
if ($ok) {
    $steps[] = ['ok','✅','قاعدة البيانات موجودة وجاهزة: '.DB_NAME];
}


// 3. Import SQL
if ($ok) {
    try {
        $rawSql = base64_decode('');
        $rawSql = ltrim($rawSql, "\xEF\xBB\xBF"); // remove BOM

        $pdo->exec("SET FOREIGN_KEY_CHECKS=0; SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO'; SET NAMES utf8mb4;");

        // Split SQL by statement-ending semicolons (safe split)
        $delim = ";\n";
        $parts  = explode($delim, $rawSql);
        $count  = 0;
        $warns  = 0;
        foreach ($parts as $stmt) {
            $stmt = trim($stmt);
            if ($stmt === '' || substr($stmt,0,2)==='--' || substr($stmt,0,2)==='/*') continue;
            try {
                $pdo->exec($stmt);
                $count++;
            } catch (PDOException $ex) {
                $warns++;
                if ($warns <= 5) {
                    $steps[] = ['warn2','⚠',htmlspecialchars(substr($ex->getMessage(),0,150))];
                }
            }
        }
        $pdo->exec("SET FOREIGN_KEY_CHECKS=1;");
        $steps[] = ['ok','✅',"تم استيراد $count جملة SQL".($warns?" ($warns تحذيرات غير حرجة)":'')];
    } catch (Exception $e) {
        $steps[] = ['err','❌','خطأ في الاستيراد: '.$e->getMessage()]; $ok=false;
    }
}

// Print steps
foreach ($steps as $s) {
    echo "<div class='step {$s[0]}'><span class='icon'>{$s[1]}</span><span>{$s[2]}</span></div>\n";
}

// Self-delete
$selfDeleted = false;
if ($ok) {
    $selfDeleted = @unlink(__FILE__);
    if ($selfDeleted) {
        echo "<div class='step ok'><span class='icon'>🗑</span><span>تم حذف ملف المثبّت تلقائياً — File self-deleted ✓</span></div>\n";
    } else {
        echo "<div class='step err'><span class='icon'>⚠</span><span>لم يتم حذف الملف تلقائياً — يرجى حذفه يدوياً فوراً!</span></div>\n";
    }
}
